import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import WIMCTourVideo, { useWIMCTour } from "../WIMCTourVideo/WIMCTourVideo";
import "./Home.css";

function Home() {
  // Single state: both "show container" and "start animation" happen together.
  // CSS animation (not transition) always plays from the closed position, so
  // there is no race between visibility and transform — no snap on page refresh.
  const [doorsOpen, setDoorsOpen] = useState(false);
  const navigate = useNavigate();

  const { isOpen: isTourOpen, openTour, closeTour } = useWIMCTour();

  const handleExploreClick = () => {
    setDoorsOpen(true);
    // Navigate slightly after the 4 s animation completes
    setTimeout(() => {
      navigate("/closet-data");
    }, 4500);
  };

  return (
    <>
      <main className="home">
        {/* Tour button — hidden once doors open */}
        {!doorsOpen && (
          <div className="home__tour-banner">
            <button onClick={openTour} className="home__tour-btn">
              🎬 Watch App Tour
            </button>
          </div>
        )}

        <section className="home__content">
          <header className="home__header">
            <h1 className="home__title">
              Welcome to What's In My Closet (WIMC)
            </h1>
            <p className="home__description">
              Organize and manage your closet effortlessly. Add, view, and
              donate your clothing items.
            </p>
          </header>
          <div className="home__actions">
            <button onClick={handleExploreClick} className="home__link">
              Explore Your Closet
            </button>
          </div>
          <footer className="home__footer">
            <p>Manage your closet with ease!</p>
          </footer>
        </section>

        {/* door-container: is-visible shows the closet-interior background;
            is-open triggers the CSS keyframe animation from closed → open */}
        <div className={`door-container${doorsOpen ? " is-visible is-open" : ""}`}>
          <div className="door-left"></div>
          <div className="door-right"></div>
        </div>
      </main>

      <WIMCTourVideo isOpen={isTourOpen} onClose={closeTour} autoPlay={true} />
    </>
  );
}

export default Home;

